using LJCNetCommon5;

// Check for missing argument of type: string with no value, null, 
private void CheckArgument()
{
  var methodName = "CheckArgument()";

  // Test Method
  var value = LJC.CheckArgument("X", "StringArg");

  var result = value.ToString();
  var compare = "True";
  TestCommon.Write($"{methodName}1", result, compare);

  value = LJC.CheckArgument(3, "IntArg");
  result = value.ToString();
  compare = "True";
  TestCommon.Write($"{methodName}2", result, compare);

  value = LJC.CheckArgument(3.14, "FloatArg");
  result = value.ToString();
  compare = "True";
  TestCommon.Write($"{methodName}3", result, compare);

  List<string> list = [];
  value = LJC.CheckArgument(list, "ListArg");
  result = value.ToString();
  compare = "True";
  TestCommon.Write($"{methodName}4", result, compare);

  DataTable dataTable = new();
  value = LJC.CheckArgument(dataTable, "DataTableArg");
  result = value.ToString();
  compare = "True";
  TestCommon.Write($"{methodName}5", result, compare);
}

using LJCNetCommon5;

/// <summary>Sort and search on Name value.</summary>
public class NameComparer : IComparer<ClassName>
{
  // Compares two objects.
  /// <include path='members/Compare/*' file='../../../LJCUtilities/LJCGenDoc5/Common/Data.xml'/>
  public int Compare(ClassName x, ClassName y)
  {
    int retValue;

    retValue = LJC.CompareNull(x, y);
    if (LJCNetString.CompareNotNullOrEqual == retValue)
    {
      retValue = LJC.CompareNull(x?.Name, y?.Name);
      if (LJCNetString.CompareNotNullOrEqual == retValue)
      {
        // Case sensitive.
        //retValue = x!.Name!.CompareTo(y?.Name);

        // Not case sensitive.
        retValue = string.Compare(x.Name, y.Name, true);
      }
    }
    return retValue;
  }
}

