// Creates a byte array from text.
private static void TextToBytes()
{
  // Setup
  string text = "Text";

  // Creates a byte array from text.
  byte[] bytes = LJC.TextToBytes(text);

  // Check the text.
  text = LJC.BytesToText(bytes);
  // text = "Text"
}

using System.IO;
using LJCNetCommon5;

// Copies a memory stream to a byte array.
private static void MemStreamToBytes()
{
  // Setup
  byte[] textBytes;
  // Creates a memory stream from a string.
  using (Stream stream = LJC.StringToMemStream("Text"))
  {
    // Copies a memory stream to a byte array.
    textBytes = LJC.MemStreamToBytes(stream);
  }

  // Check the text.
  string text = LJC.BytesToText(textBytes);
  // text = "Text"
}

using System.IO;
using LJCNetCommon5;

// Copies a byte array to a memory stream.
private static void BytesToMemStream()
{
  // Setup
  // Creates a byte array from text.
  byte[] bytes = LJC.TextToBytes("Text");

  // Copies a byte array to a memory stream.
  using (Stream stream = LJC.BytesToMemStream(bytes))
  {
    // Check the text.
    string text = LJC.MemStreamToString(stream);
    // text = "Text"
  }
}

using LJCNetCommon5;

// Creates a string from a memory stream.
private static void MemStreamToString()
{
  // Setup
  // Creates a memory stream from a string.
  using (Stream stream = LJCLJC.StringToMemStream("Text"))
  {
    // Creates a string from a memory stream.
    string text = LJCLJC.MemStreamToString(stream);
    // text = "Text"
  }
}

using LJCNetCommon5;

// Creates a memory stream from a string.
private static void StringToMemStream()
{
  // Creates a memory stream from a string.
  using (Stream stream = LJCLJC.StringToMemStream("Text"))
  {
    // Check the text.
    string text = LJCLJC.MemStreamToString(stream);
    // text = "Text"
  }
}

using LJCNetCommon5;

// Decodes an encoded XML string.
private static void XmlDecode()
{
  // Setup
  string xml = "<text>Here & There</text>";
  // Encodes a string with XML escape values.
  string encoded = LJCLJC.XmlEncode(xml);

  // Decodes an encoded XML string.
  string text = LJCLJC.XmlDecode(encoded);
  // text = "Text"
}

using LJCNetCommon5;

// Encodes a string with XML escape values.
private static void XmlEncode()
{
  // Setup
  string xml = "<text>Here & There</text>";

  // Encodes a string with XML escape values.
  string encoded = LJC.XmlEncode(xml);

  // Check the text.
  string text = LJC.XmlDecode(encoded);
  // text = "Text"
}
